export function getTopicParentName(topic: QuranTopic): string | null {
  return topic.parentId === null ? null : (TOPIC_PARENTS[topic.parentId] ?? null);
}

export function getTopicAyahRefs(topic: QuranTopic): Array<{ surah: number; ayah: number }> {
  if (!topic.ayahs) return [];
  return topic.ayahs.split(",").map((ref) => {
    const [surah, ayah] = ref.split(":").map(Number);
    return { surah, ayah };
  });
}

/** How many ayahs carry this topic. */
export function getTopicAyahCount(topic: QuranTopic): number {
  return topic.ayahs ? topic.ayahs.split(",").length : 0;
}

/** Arabic label for a topic's bundled source (shown in the topic list). */
export function getTopicSourceLabel(topic: QuranTopic): string {
  if (topic.source === "qul") return "مكتبة القرآن العالمية (QUL)";
  if (topic.source === "both") return "Quranpedia + مكتبة القرآن العالمية (QUL)";
  return "Quranpedia";
}
